INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N027-01','CN0070','S027-01','分质站及园区边界','7.2.2 pp191–194','厂内169.74m³/d设计进站、300m³/d能力；合计172.14m³/d纳管。园区5000m³/d已建，环评称运行1700–2400，出水工业回用；共享非厂区专用。物理污泥单列一般固废，含重金属和生化泥资质处置。物理过滤和生物接触氧化不是膜分离。截图失败，按文本录。','WEB_PRIMARY','公开正文/文本摘录；未归档原件','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N027-02','CN0070','S027-02','审批要求','三（三）','生产各股及生活水处理后纳管；批复要求GB26452-2011表2，环评部分生活水化粪池单列。批复不证明建成。','WEB_PRIMARY','公开正文/文本摘录；未归档原件','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N027-03','CN0070','S027-03','经营许可','公告正文','许可证6505220132；金光大道5号公司住所，伊州区南部循环经济产业园设施地址；N42°41′55.73″、E93°24′57.54″；HW50 772-007-50；总16000t/a对应20000m³/a。','WEB_PRIMARY','公开正文/文本摘录；未归档原件','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N027-04','CN0070','S027-04','现场生产','2025-11-18现场','两条自动化清洗线、各12槽；先清灰、清洗，能再生者补活性负载，不能再生者资源化。仅确认生产报道时运行，不等于污水站验收或当前实际处理量。','WEB_SECONDARY','公开正文/文本摘录；未归档原件','2026-11-27');
