INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('A027-01','R027-01','CN0070','regeneration-2023-design','screening',1,'分质减量、回用及稳定达标','优先做含钒水金属回收及重金属预处理验证；生化出水低SS且具回用需求时试验UF+RO/NF，浓水须另行合法闭合','conditional','须先确认实际水质、设施及浓水合法去向；不把候选当实装','300m³/d厂内设计；环评正文列完整核心工艺但未验证实际建设变动，园区5000m³/d单列；不以无膜词出现即确认为无膜','INFERRED工程候选；实际量/报价不外推','各分流实测TDS、离子、金属、氨和COD，膜回用目标、浓水去向、全成本','采样分流、烧杯除金属、膜试验、盐与水量衡算及实际纳管与回用成本对比','原三系统稳定运行、提高逆流清洗和分质回用',2,1,NULL,NULL,NULL,NULL,'设计明确活化水高钒氨COD及多金属，需先预处理；分流和重捕已有设计，不代表实际风险已全核','2026-11-27');
