INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N027-05','CN0184','S027-05','十股分质与MVR','3.5.2.1、图3.5.2-2，pp112–115','N1/N2除重金属达一类限值后蒸发；N3/N4高盐氧化及固液分离后蒸发，盐及母液外送、冷凝水低盐缓冲。N5与部分N6除总氮，其余N6低盐处理；N7入中和后缓冲；N8/N9阀切换；N10银墨水监测后除总氮。七单元能力及2023/24实量已结构化，勿加总上下游。全厂实际接管池2024 72581m³。','WEB_PRIMARY','公开正文/文本摘录；未归档原件','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N027-06','CN0184','S027-05','监测及局限','表3.5.2-4、5 pp115–116','2024接管口COD5.35–310.49，氨氮0.07–32.55mg/L，pH7.9–8.9；TDS三个样4490/5900/8030mg/L。总排口和车间一类口不可混。粪大肠菌群3700/280/2800，原表未清楚显示单位，暂保留摘要；二甲苯异构体检出限不同，不统一填。原表多个合并日期格，截图404，保留样本序号不猜日期。','WEB_PRIMARY','公开正文/文本摘录；未归档原件','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N027-07','CN0184','S027-05','第三批改造及事故池','3.6.5及4.6.2','现有事故池2050m³，正常水位≤10%，非日处理量。2021增生化除总氮后，2025拟不含二氯甲烷有机水进入除氮装置；含二氯甲烷仍委外；部分源强表涉商业秘密隐藏，不推算。','WEB_PRIMARY','公开正文/文本摘录；未归档原件','2026-11-27');
