INSERT INTO membrane_reviews (review_id,site_id,diagram_id,scope_key,stage,period,revision,presence,source_id,evidence_basis,gaps,updated_on) VALUES ('R027-02','CN0184','D027-02','existing-2025-ten-streams','historical','2023–2024实绩及2025环评回顾',1,'not_identified','S027-05','2025环评回顾现有站；各单元能力及2023/24实量明示；不将厂区混合水当催化剂单线，图中低盐缓冲后具体连接不猜','2026现行膜清单、流股实测组成、MVR电耗、结晶盐处置费、回用需求及吨水成本','2026-11-27');
INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('A027-02','R027-02','CN0184','existing-2025-ten-streams','screening',1,'分质减量、回用及稳定达标','既有重金属预处理后先筛选高盐流股的NF/ED预浓缩以降低MVR负荷；低盐出水回用需按TDS/TOC及贵金属回收价值决定UF+RO；不得按全厂72581m³直接定设备','conditional','须先确认实际水质、设施及浓水合法去向；不把候选当实装','2025环评回顾现有站；各单元能力及2023/24实量明示；不将厂区混合水当催化剂单线，图中低盐缓冲后具体连接不猜','INFERRED工程候选；实际量/报价不外推','分股TDS及盐种、金属、TOC、渗透压、MVR实耗、盐/母液处置单价、回用需求','分流采样、金属回收、膜相容性/污染试验、蒸发电耗与浓缩节约敏感性','优化现有沉淀、树脂和MVR，不改造或源头分流',2,1,1,NULL,NULL,NULL,'实际接管TDS样4490–8030且多金属分流；已有预处理、MVR及外送设计，但膜进水与浓水是否适配待核','2026-11-27');
