INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('A027-03','R027-03','CN0184','third-batch-organic-design','screening',1,'分质减量、回用及稳定达标','先验证生化耐受和毒性隔离；不直接推荐压力膜处理浓有机液，处理后出水回用另评估','conditional','须先确认实际水质、设施及浓水合法去向；不把候选当实装','第三批拟改变不含二氯甲烷液的处理；原两类均委外；不当已运行','INFERRED工程候选；实际量/报价不外推','有机物组分、毒性、实际量、膜兼容性、危废成本','生化抑制试验、物料衡算及非膜与深度回用成本比较','保持合规委外或原生化设计',NULL,NULL,NULL,NULL,NULL,NULL,'六维缺乏完整依据，未评分','2026-11-27');
